import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n <= 1:
        return

    idx = 1
    adj = []
    for i in range(n):
        row = list(map(int, data[idx:idx+n]))
        adj.append(row)
        idx += n

    INF = float('inf')
    key = [INF] * n
    parent = [-1] * n
    mst_set = [False] * n

    key[0] = 0

    for _ in range(n):
        u = -1
        min_val = INF
        for v in range(n):
            if not mst_set[v] and key[v] < min_val:
                min_val = key[v]
                u = v

        if u == -1:
            break

        mst_set[u] = True

        if parent[u] != -1:
            v_parent = parent[u]
            w = adj[v_parent][u]
            print(f"{v_parent + 1} {u + 1} {w}")

        for v in range(n):
            if u != v and adj[u][v] > 0 and not mst_set[v] and adj[u][v] < key[v]:
                key[v] = adj[u][v]
                parent[v] = u

if __name__ == "__main__":
    main()
